    /**
     * @method
     * @name hitbtc#fetchMarkets
     * @description retrieves data on all markets for hitbtc
     * @see https://api.hitbtc.com/#symbols
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} an array of objects representing market data
     */
    public CompletableFuture<Object> fetchMarkets(Map<String, Object> parameters)
    {

        return BaseExchange.supplyAsync(() -> {

            Map<String, Object> response = (this.publicGetPublicSymbol(parameters)).join();
            //
            //     {
            //         "AAVEUSDT_PERP":{
            //             "type":"futures",
            //             "expiry":null,
            //             "underlying":"AAVE",
            //             "base_currency":null,
            //             "quote_currency":"USDT",
            //             "quantity_increment":"0.01",
            //             "tick_size":"0.001",
            //             "take_rate":"0.0005",
            //             "make_rate":"0.0002",
            //             "fee_currency":"USDT",
            //             "margin_trading":true,
            //             "max_initial_leverage":"50.00"
            //         },
            //         "MANAUSDT":{
            //             "type":"spot",
            //             "base_currency":"MANA",
            //             "quote_currency":"USDT",
            //             "quantity_increment":"1",
            //             "tick_size":"0.0000001",
            //             "take_rate":"0.0025",
            //             "make_rate":"0.001",
            //             "fee_currency":"USDT",
            //             "margin_trading":true,
            //             "max_initial_leverage":"5.00"
            //         },
            //     }
            //
            List<Object> result = new ArrayList<Object>(Arrays.asList());
            List<String> ids = new ArrayList<String>(response.keySet());
            for (var i = 0; i < ((List<?>)ids).size(); i++)
            {
                String id = (ids == null || i < 0 || i >= ids.size() ? null : ids.get(i));
                if (Helpers.isTrue(id.endsWith(((String)"_BQX"))))
                {
                    continue;
                }
                Map<String, Object> market = (Map<String, Object>) this.safeDict(response, id, (Object) null);
                String marketType = this.safeString(market, "type");
                Long expiry = this.safeInteger(market, "expiry");
                Boolean contract = (java.util.Objects.equals(marketType, "futures"));
                Boolean spot = (java.util.Objects.equals(marketType, "spot"));
                Boolean marginTrading = (Boolean) this.safeBool(market, "margin_trading", false);
                Boolean margin = Boolean.TRUE.equals(spot) && Boolean.TRUE.equals(marginTrading);
                Boolean future = (!java.util.Objects.equals(expiry, null));
                Boolean swap = (Boolean.TRUE.equals(contract) && !Boolean.TRUE.equals(future));
                Boolean option = false;
                String baseId = this.safeString2(market, "base_currency", "underlying");
                String quoteId = this.safeString(market, "quote_currency");
                String feeCurrencyId = this.safeString(market, "fee_currency");
                String base = this.safeCurrencyCode(baseId, (Map<String, Object>) null);
                String quote = this.safeCurrencyCode(quoteId, (Map<String, Object>) null);
                if ((java.util.Objects.equals(base, null)) || (java.util.Objects.equals(quote, null)))
                {
                    continue;
                }
                String feeCurrency = this.safeCurrencyCode(feeCurrencyId, (Map<String, Object>) null);
                String settleId = null;
                String settle = null;
                String symbol = ((base + "/") + quote);
                String type = "spot";
                Double contractSize = null;
                Boolean linear = null;
                Boolean inverse = null;
                if (Boolean.TRUE.equals(contract))
                {
                    contractSize = this.parseNumber("1");
                    settleId = feeCurrencyId;
                    settle = this.safeCurrencyCode(settleId, (Map<String, Object>) null);
                    linear = ((!java.util.Objects.equals(quote, null)) && (java.util.Objects.equals(quote, settle)));
                    inverse = !Boolean.TRUE.equals(linear);
                    symbol = ((symbol + ":") + settle);
                    if (Boolean.TRUE.equals(future))
                    {
                        symbol = ((symbol + "-") + expiry);
                        type = "future";
                    } else
                    {
                        type = "swap";
                    }
                }
                String lotString = this.safeString(market, "quantity_increment");
                String stepString = this.safeString(market, "tick_size");
                Double lot = this.parseNumber(lotString);
                Double step = this.parseNumber(stepString);
                ((List<Object>)result).add(Helpers.newMap(
                    "id", id,
                    "symbol", symbol,
                    "base", base,
                    "quote", quote,
                    "settle", settle,
                    "baseId", baseId,
                    "quoteId", quoteId,
                    "settleId", settleId,
                    "type", type,
                    "spot", spot,
                    "margin", margin,
                    "swap", swap,
                    "future", future,
                    "option", option,
                    "active", true,
                    "contract", contract,
                    "linear", linear,
                    "inverse", inverse,
                    "taker", this.safeNumber(market, "take_rate", (Object) null),
                    "maker", this.safeNumber(market, "make_rate", (Object) null),
                    "contractSize", contractSize,
                    "expiry", expiry,
                    "expiryDatetime", null,
                    "strike", null,
                    "optionType", null,
                    "feeCurrency", feeCurrency,
                    "precision", new HashMap<String, Object>() {{
                        put( "amount", lot );
                        put( "price", step );
                    }},
                    "limits", new HashMap<String, Object>() {{
                        put( "leverage", new HashMap<String, Object>() {{
                            put( "min", Hitbtc.this.parseNumber("1") );
                            put( "max", Hitbtc.this.safeNumber(market, "max_initial_leverage", 1) );
                        }} );
                        put( "amount", new HashMap<String, Object>() {{
                            put( "min", lot );
                            put( "max", null );
                        }} );
                        put( "price", new HashMap<String, Object>() {{
                            put( "min", step );
                            put( "max", null );
                        }} );
                        put( "cost", new HashMap<String, Object>() {{
                            put( "min", Hitbtc.this.parseNumber(Precise.stringMul(lotString, stepString)) );
                            put( "max", null );
                        }} );
                    }},
                    "created", null,
                    "info", market
                ));
            }
            return result;
        });

    }

